/* Live UX fix: show the Home QR scanner, help guests, and allow table-link sharing. */
(function () {
  function element(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text != null) node.textContent = text;
    return node;
  }
  function install() {
    if (window.MM_QR_HOME_PATCH) return;
    window.MM_QR_HOME_PATCH = true;

    var style = element('style');
    style.id = 'mm-qr-home-patch-style';
    style.textContent = '#scan-table-btn{display:inline-flex!important;margin-top:8px}';
    document.head.appendChild(style);

    var note = document.getElementById('home-no-install');
    if (note) note.textContent = 'Scan the QR sticker on your table, or tap Scan table QR to use the in-app scanner. If the sticker is missing, ask your waiter to share the exact table link.';

    var shortcutHost = document.querySelector('.home-shortcuts');
    if (shortcutHost && !document.getElementById('home-table-qr-help')) {
      var tile = element('div', 'home-shortcut');
      var helpButton = element('button', 'home-icon-btn');
      helpButton.type = 'button';
      helpButton.id = 'home-table-qr-help';
      helpButton.setAttribute('aria-label', 'Table QR help');
      helpButton.title = 'Table QR help';
      helpButton.appendChild(element('span', '', '📱'));
      helpButton.addEventListener('click', function () {
        var modal = document.getElementById('table-qr-help-modal');
        if (modal) modal.classList.add('on');
      });
      tile.appendChild(helpButton);
      tile.appendChild(element('span', 'home-shortcut-label', 'Table QR'));
      shortcutHost.insertBefore(tile, shortcutHost.firstChild);
    }

    var helpModal = document.getElementById('table-qr-help-modal');
    if (!helpModal) {
      helpModal = element('div', 'modal');
      helpModal.id = 'table-qr-help-modal';
      var helpBox = element('div', 'box');
      var helpTitle = element('h3', 'gold center', '📱 Table QR help');
      var helpText = element('p', '', 'At your table, scan the printed QR with your phone camera, or tap Scan table QR on Home to use the in-app scanner. The QR opens the exact table menu automatically.');
      helpText.style.margin = '10px 0 8px';
      var staffText = element('p', 'muted', 'No sticker? Ask your waiter to share the correct table link. Staff can sign in, open Owner/Admin → QR, select the table, then copy/share its link or print the QR sheet. Please do not select a different table.');
      staffText.style.cssText = 'font-size:12px;margin-bottom:10px';
      var scanBtn = element('button', 'btn btn-main', 'Scan table QR now');
      scanBtn.type = 'button';
      scanBtn.addEventListener('click', function () {
        helpModal.classList.remove('on');
        if (typeof window.openScan === 'function') window.openScan();
      });
      var closeBtn = element('button', 'btn btn-soft', 'Close');
      closeBtn.type = 'button';
      closeBtn.style.marginTop = '8px';
      closeBtn.addEventListener('click', function () { helpModal.classList.remove('on'); });
      helpBox.appendChild(helpTitle);
      helpBox.appendChild(helpText);
      helpBox.appendChild(staffText);
      helpBox.appendChild(scanBtn);
      helpBox.appendChild(closeBtn);
      helpModal.appendChild(helpBox);
      document.body.appendChild(helpModal);
    }

    var qrCode = document.getElementById('qr-code');
    if (qrCode && !document.getElementById('qr-table-link-controls')) {
      var controls = element('div');
      controls.id = 'qr-table-link-controls';
      var description = element('p', 'muted', 'Share this exact table link with guests, or print the QR and place it on that table.');
      description.style.cssText = 'font-size:12px;margin:0 0 4px';
      var field = element('input');
      field.id = 'qr-table-url';
      field.type = 'url';
      field.readOnly = true;
      field.setAttribute('aria-label', 'Direct link for this table');
      field.style.cssText = 'width:100%;padding:10px;border-radius:10px;border:1px solid var(--line);background:rgba(0,0,0,.25);color:var(--text);font-size:12px;margin:4px 0 8px';
      var row = element('div');
      row.style.cssText = 'display:flex;gap:8px;margin-bottom:8px';
      var copy = element('button', 'btn btn-soft', 'Copy table link');
      copy.type = 'button'; copy.style.flex = '1';
      var share = element('button', 'btn btn-main', 'Share link');
      share.type = 'button'; share.style.flex = '1';
      row.appendChild(copy); row.appendChild(share);
      controls.appendChild(description); controls.appendChild(field); controls.appendChild(row);
      qrCode.parentNode.insertBefore(controls, qrCode.nextSibling);

      function selectedNumber(value) {
        var raw = String(value || window.MM_CURRENT_QR_TABLE || window.currentQRCodeTable || '').replace(/\D/g, '');
        var number = parseInt(raw, 10);
        return number >= 1 && number <= 50 ? String(number).padStart(2, '0') : '';
      }
      function tableLink(number) {
        return typeof window.tableURL === 'function'
          ? window.tableURL(number)
          : window.location.origin + window.location.pathname + '?table=' + encodeURIComponent(number);
      }
      window.copyCurrentTableLink = function () {
        var number = selectedNumber();
        if (!number) { if (window.toast) window.toast('Choose a table QR first.'); return; }
        var url = tableLink(number);
        field.value = url;
        if (navigator.clipboard && window.isSecureContext) {
          navigator.clipboard.writeText(url).then(function () {
            if (window.toast) window.toast('Table link copied');
          }).catch(function () {
            field.focus(); field.select();
            if (window.toast) window.toast('Select and copy the table link above.');
          });
        } else {
          field.focus(); field.select();
          if (window.toast) window.toast('Select and copy the table link above.');
        }
      };
      window.shareCurrentTableLink = function () {
        var number = selectedNumber();
        if (!number) { if (window.toast) window.toast('Choose a table QR first.'); return; }
        var url = tableLink(number);
        if (navigator.share) {
          navigator.share({ title: 'Mirch Masaala · Table ' + number, text: 'Open the menu for this table:', url: url })
            .catch(function (e) { if (!e || e.name !== 'AbortError') window.copyCurrentTableLink(); });
        } else window.copyCurrentTableLink();
      };
      copy.addEventListener('click', function () { window.copyCurrentTableLink(); });
      share.addEventListener('click', function () { window.shareCurrentTableLink(); });
      var oldShowQR = window.showQR;
      if (typeof oldShowQR === 'function' && !window.MM_QR_LINK_WRAPPED) {
        window.MM_QR_LINK_WRAPPED = true;
        window.showQR = function (value) {
          var result = oldShowQR.apply(this, arguments);
          var number = selectedNumber(value);
          window.MM_CURRENT_QR_TABLE = number;
          if (number) field.value = tableLink(number);
          return result;
        };
      }
    }

    // Convert the existing setup log into a visible owner-facing alert.
    window.MM_ROLE_NOTIFICATIONS_SETUP_ERROR = window.MM_ROLE_NOTIFICATIONS_SETUP_ERROR || '';
    var oldDrawAlerts = window.drawAlerts;
    if (typeof oldDrawAlerts === 'function' && !window.MM_ALERT_SETUP_WRAPPED) {
      window.MM_ALERT_SETUP_WRAPPED = true;
      window.drawAlerts = function () {
        oldDrawAlerts.apply(this, arguments);
        var host = document.getElementById('a-alerts');
        if (!host) return;
        var message = String(window.MM_ROLE_NOTIFICATIONS_SETUP_ERROR || '');
        var banner = document.getElementById('shared-notification-setup-warning');
        if (!message) { if (banner) banner.remove(); return; }
        if (!banner) {
          banner = element('div', 'setup');
          banner.id = 'shared-notification-setup-warning';
          banner.style.cssText = 'border-color:rgba(232,106,106,.6);margin-bottom:12px';
          host.insertBefore(banner, host.firstChild);
        }
        banner.textContent = '';
        banner.appendChild(element('h3', '', '⚠️ Shared notifications need setup'));
        banner.appendChild(element('p', '', 'Cross-device staff alerts could not be loaded. Apply supabase/role-notifications.sql in Supabase SQL Editor after supabase/setup-live.sql. For lock-screen push alerts, also apply supabase/staff-push-notifications.sql, configure push secrets, and deploy the send-staff-push Edge Function.'));
        var detail = element('p', 'muted', 'Details: ' + message.slice(0, 220));
        detail.style.cssText = 'font-size:11px;margin-top:5px';
        banner.appendChild(detail);
      };
    }

    var oldInfo = console.info;
    if (oldInfo && !window.MM_ALERT_INFO_WRAPPED) {
      window.MM_ALERT_INFO_WRAPPED = true;
      console.info = function () {
        try {
          if (String(arguments[0] || '').indexOf('[Mirch Masaala alerts] Run supabase/role-notifications.sql') === 0) {
            var error = arguments[1];
            window.MM_ROLE_NOTIFICATIONS_SETUP_ERROR = error && error.message ? String(error.message) : String(error || 'Shared notification SQL is not installed.');
            if (window.role === 'admin' && typeof window.drawAlerts === 'function') window.drawAlerts();
          }
        } catch (e) {}
        return oldInfo.apply(console, arguments);
      };
    }
    var oldRender = window.renderRoleNotifications;
    if (typeof oldRender === 'function' && !window.MM_ALERT_RENDER_WRAPPED) {
      window.MM_ALERT_RENDER_WRAPPED = true;
      window.renderRoleNotifications = function () {
        window.MM_ROLE_NOTIFICATIONS_SETUP_ERROR = '';
        var result = oldRender.apply(this, arguments);
        if (window.role === 'admin' && typeof window.drawAlerts === 'function') window.drawAlerts();
        return result;
      };
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', install, { once: true });
  else install();
})();
